import { chromium } from 'playwright';
import { pathToFileURL } from 'node:url';
import { resolve } from 'node:path';
import { mkdirSync } from 'node:fs';
const browser=await chromium.launch({headless:true});
const page=await browser.newPage({viewport:{width:390,height:844},deviceScaleFactor:1});
const errors=[];page.on('pageerror',e=>errors.push(String(e)));mkdirSync('ui-check',{recursive:true});
await page.goto(pathToFileURL(resolve('app/src/main/assets/index.html')).href);
await page.screenshot({path:'ui-check/lobby.png',fullPage:true});
await page.locator('#quick').click();await page.locator('#buyForm button').click();
await page.locator('#call').waitFor();
await page.screenshot({path:'ui-check/table.png',fullPage:true});
await page.locator('#call').click();await page.locator('#raise').click();await page.locator('#fold').click();
await page.locator('#next').waitFor();await page.locator('#exit').click();
await page.locator('[data-page="clubs"]').click();await page.locator('#newClub').click();await page.locator('#clubName').fill('River Club');await page.locator('#clubForm button').click();await page.locator('.club-card').waitFor();
await page.screenshot({path:'ui-check/clubs.png',fullPage:true});
await page.setViewportSize({width:360,height:740});await page.locator('[data-page="lobby"]').click();
if(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth))throw Error('Horizontal overflow at 360px');
if(errors.length)throw Error(errors.join('\n'));
console.log('PASS: mobile navigation, play, bet, fold, history persistence, club creation, 360px overflow check.');await browser.close();
